import{_ as a,o as t,c as s,a2 as n}from"./chunks/framework.DncwoWA8.js";const i="/projects/ai-skills/diagrams/implement-a-task.svg",f=JSON.parse('{"title":"Implement a planned task","description":"","frontmatter":{"title":"Implement a planned task"},"headers":[],"relativePath":"workflows/implement-a-task.md","filePath":"workflows/implement-a-task.md"}'),r={name:"workflows/implement-a-task.md"};function o(l,e,p,c,d,h){return t(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="implement-a-planned-task" tabindex="-1">Implement a planned task <a class="header-anchor" href="#implement-a-planned-task" aria-label="Permalink to &quot;Implement a planned task&quot;">​</a></h1><p>Turn one agreed task into tested behavior and reviewed changes.</p><p>Start with a task from planning or equally clear direct scope. Finish with the requested behavior, verification evidence, affected documentation, and resolved or disclosed review findings. Do not repeat planning merely because a task arrived without a separate brief.</p><h2 id="workflow" tabindex="-1">Workflow <a class="header-anchor" href="#workflow" aria-label="Permalink to &quot;Workflow&quot;">​</a></h2><p><img src="'+i+`" alt="Task implementation with optional scaffolding, TDD, independent review, and correction loops."></p><p><a href="/projects/ai-skills/diagrams/implement-a-task.html" class="vp-raw">Open interactive diagram</a> · <a href="/projects/ai-skills/diagrams/implement-a-task.svg">Download SVG</a> · <a href="/projects/ai-skills/diagram-sources/implement-a-task.json">Editable source</a></p><p>The diagram shows suggested handoffs, not automatic execution or new instruction dependencies. Select a node in the interactive diagram for its source references.</p><details><summary>Read the flow as text</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span>An agreed task</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Optional /scaffold → STOP</span></span>
<span class="line"><span>    ↓ explicit instruction</span></span>
<span class="line"><span>/coding-with-rules</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Checks → /code-review if selected</span></span>
<span class="line"><span>    ├─ correction</span></span>
<span class="line"><span>    │    ↓</span></span>
<span class="line"><span>    │  /coding-with-rules → checks</span></span>
<span class="line"><span>    └─ scope changes → planning</span></span></code></pre></div></details><p>If the existing structure is sufficient, go directly to implementation. Scaffolding is useful when the file structure or interfaces need their own review.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><p>Read the task, acceptance criteria, project instructions, affected code, and tests. Confirm the permitted changes and <a href="/projects/ai-skills/workflows/supporting-tools.html#before-you-start">execution safeguards</a>.</p><p>Use <a href="/projects/ai-skills/skills/coding-with-rules.html"><code>coding-with-rules</code></a> throughout source design, scaffolding, implementation, testing, and corrections. It loads the base <code>coding</code> instructions and the relevant language references.</p><p>Return to <a href="/projects/ai-skills/workflows/plan-a-project.html">planning</a> if a missing requirement would force you to invent behavior. A local implementation choice that preserves agreed contracts does not require restarting the entire planning flow.</p><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><h3 id="_1-establish-structure-only-when-needed" tabindex="-1">1. Establish structure only when needed <a class="header-anchor" href="#_1-establish-structure-only-when-needed" aria-label="Permalink to &quot;1. Establish structure only when needed&quot;">​</a></h3><p>Use <a href="/projects/ai-skills/skills/scaffold.html"><code>scaffold</code></a> for approved source skeletons. Agree the exact file-level scope, preserve working behavior, and leave unfinished callables explicitly unfinished.</p><p>Stop after the structural handoff. The current skill requires a separate explicit instruction before implementing behavior. A compiled skeleton is not a completed feature, and scaffold approval does not authorize the next phase.</p><p>For a task that only changes an existing function or behavior, omit this branch.</p><h3 id="_2-implement-one-behavior-slice" tabindex="-1">2. Implement one behavior slice <a class="header-anchor" href="#_2-implement-one-behavior-slice" aria-label="Permalink to &quot;2. Implement one behavior slice&quot;">​</a></h3><p>Apply <code>coding-with-rules</code> to the smallest change that satisfies the task. Preserve public contracts unless the task explicitly changes them.</p><p>Tests are required for changed behavior even when you do not choose TDD. Cover the relevant public behavior, boundaries, failures, and security regressions. Use configured project checks rather than adding tools or changing thresholds without approval.</p><h3 id="_3-use-the-test-first-variant-when-selected" tabindex="-1">3. Use the test-first variant when selected <a class="header-anchor" href="#_3-use-the-test-first-variant-when-selected" aria-label="Permalink to &quot;3. Use the test-first variant when selected&quot;">​</a></h3><p>With <a href="/projects/ai-skills/skills/tdd.html"><code>tdd</code></a>, agree the public test boundaries before writing tests. Confirmed boundaries in the specification can supply that agreement.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span>One agreed behavior</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>/tdd: observe one failing test</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>/coding-with-rules: minimal change</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Observe green</span></span>
<span class="line"><span>    ├─ next behavior → repeat</span></span>
<span class="line"><span>    └─ task complete → review</span></span></code></pre></div><p>Keep TDD and coding guidance active together. Do not write all tests first and all implementation afterward.</p><p>The local TDD skill defines a red/green loop. It places refactoring in the review stage rather than inside that loop. Corrective refactoring must preserve required behavior and pass the relevant checks.</p><h3 id="_4-review-and-correct-the-change" tabindex="-1">4. Review and correct the change <a class="header-anchor" href="#_4-review-and-correct-the-change" aria-label="Permalink to &quot;4. Review and correct the change&quot;">​</a></h3><p>Run applicable project quality gates and inspect the full diff against the task. Update affected reader guidance with <a href="/projects/ai-skills/skills/document-project.html"><code>document-project</code></a>.</p><p>Use <a href="/projects/ai-skills/skills/code-review.html"><code>code-review</code></a> when that independent review is requested and supported. It checks Standards and Spec separately against fixed Git snapshots. Read its <a href="/projects/ai-skills/workflows/supporting-tools.html#review-an-existing-change">review prerequisites</a> before invoking it.</p><p>For each actionable finding, make the bounded correction, rerun affected checks, and review again. Add a test when a finding exposes an uncovered behavior. Return to scaffolding only when revised structure needs its own approved handoff.</p><p>If a finding changes requirements or expands scope, stop for agreement in planning. Review findings are not permission for unrelated cleanup.</p><h2 id="example-implement-a-csv-quoting-task" tabindex="-1">Example: implement a CSV quoting task <a class="header-anchor" href="#example-implement-a-csv-quoting-task" aria-label="Permalink to &quot;Example: implement a CSV quoting task&quot;">​</a></h2><p>This example continues the illustrative reporting project from the planning guide. It is not an executed test.</p><p>Suppose the agreed task is to preserve CSV fields containing commas and quotes through the application&#39;s existing export interface. After loading the installed coding skills, request:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span>Implement the agreed CSV quoting task using /coding-with-rules and TDD.</span></span>
<span class="line"><span>Use the export interface and test boundaries confirmed in the specification.</span></span>
<span class="line"><span>First observe a failing test for a field containing a comma. Make it pass,</span></span>
<span class="line"><span>then cover a quoted field. Preserve filtering, columns, and permissions.</span></span>
<span class="line"><span>Update affected documentation and report the actual checks.</span></span>
<span class="line"><span>Do not commit, push, or launch reviewers without the required authorization.</span></span></code></pre></div><p>Expected evidence includes the observed red and green results, requirement coverage, the full change, and documentation impact. A review handoff also identifies the specification and an approved fixed Git comparison.</p><p>If a test boundary is still undecided, settle it before writing tests. If independent review cannot run, report that limitation rather than label the change reviewed.</p><h2 id="finish-the-task" tabindex="-1">Finish the task <a class="header-anchor" href="#finish-the-task" aria-label="Permalink to &quot;Finish the task&quot;">​</a></h2><p>Report changed behavior, acceptance-criterion results, checks and unrun reasons, documentation impact, remaining findings, and the next decision. Include the branch and workspace where project policy requires them.</p><p>Task completion does not grant commit, push, merge, or release authority. Return to the task list only after the selected deliverable is accounted for.</p><p>Focused procedures remain available for <a href="/projects/ai-skills/workflows/implement-a-small-change.html">a small approved change</a>, <a href="/projects/ai-skills/workflows/build-test-first.html">test-first work</a>, and <a href="/projects/ai-skills/workflows/scaffold-without-implementation.html">scaffold-only work</a>.</p>`,41)])])}const m=a(r,[["render",o]]);export{f as __pageData,m as default};
